/*
 * A011669  A binary m-sequence: expansion of reciprocal of x^6+x+1.
 * https://oeis.org/A011669
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = a(n-6) XOR a(n-1);
 *            a(0)=0,a(1)=0,a(2)=0,a(3)=0,a(4)=0,a(5)=1
 * Range:     u8 n <= 80, u16 n <= 80, u32 n <= 80, u64 n <= 80, u128 n <= 80,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>

seq_t a(idx_t n)
{
    /* The m‑sequence generated by 1/(x^6+x+1) has period 63.  We build the
       first 63 terms once and then index modulo 63. */

    static seq_t seq63[63];
    static bool built = false;

    if (!built)
    {
        /* buffer holding the last 6 terms */
        seq_t buf[6] = { 0, 0, 0, 0, 0, 1 };

        for (idx_t i = 0; i < 63; ++i)
        {
            if (i < 6)
            {
                seq63[i] = buf[i];            /* initial conditions */
            }
            else
            {
                /* Compute a(i) = a(i-6) XOR a(i-1) */
                seq_t next = buf[(i - 6) % 6] ^ buf[(i - 1) % 6];
                buf[i % 6] = next;
                seq63[i] = next;
            }
        }
        built = true;
    }

    return seq63[n % 63];
}
